SELECT * FROM (SELECT CASE WHEN budget >= 3121000 THEN 'high' WHEN budget >= 668000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(*) AS num_departments, COUNT(DISTINCT budget) AS unique_locations FROM departments WHERE dept_name IN ('HR', 'Sales', 'Finance') GROUP BY CASE WHEN budget >= 3121000 THEN 'high' WHEN budget >= 668000 THEN 'mid' ELSE 'low' END) AS x WHERE unique_locations >= 9;
